export type AuthCopyKey = keyof typeof AUTH_HY;

/** Replaces `{token}` placeholders without touching any other byte. */
export function hy(key: AuthCopyKey, vars?: Record<string, string | number>): string {
  const base = AUTH_HY[key];
  if (!vars) return base;
  return base.replace(/\{(\w+)\}/g, (m, name: string) =>
    Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : m,
  );
}
